  "repairable": {"zh":"控制物品是否可以通过工作台或铁砧修复。（默认值：true）","en":"Decides if the item can be repaired through crafting table/anvil. (Default: true)"},
  "settings.repairable": {"zh":"控制物品是否可以通过工作台或铁砧修复。（默认值：true）","en":"Decides if the item can be repaired through crafting table/anvil. (Default: true)"},
  "anvil_repair_item": {"zh":"控制指定物品在铁砧修复时提供的耐久度。","en":"Determines how much durability a given item provides when repairing."},
