  "prevent_break": {"zh":"控制物品耐久耗尽时是否阻止其损毁。（默认值: false）","en":"Determines whether the item is prevented from breaking when its durability runs out. (Default: false)"},
  "settings.prevent_break": {"zh":"控制物品耐久耗尽时是否阻止其损毁。（默认值: false）","en":"Determines whether the item is prevented from breaking when its durability runs out. (Default: false)"},
  "can_place": {"zh":"决定该物品材质对应的原版方块能否被放置。当你用方块类材质（如 `note_block`）作为非方块物品的基底时，将其设为 `false` 可防止玩家把它放置成方块。（默认值: false）","en":"Determines whether the vanilla block corresponding to this item's material can be placed. Set it to `false` when you use a block-like material (e.g. `note_block`) as the base for a non-block item, so players can't place it as a block. (Default: false)"},
  "settings.can_place": {"zh":"决定该物品材质对应的原版方块能否被放置。当你用方块类材质（如 `note_block`）作为非方块物品的基底时，将其设为 `false` 可防止玩家把它放置成方块。（默认值: false）","en":"Determines whether the vanilla block corresponding to this item's material can be placed. Set it to `false` when you use a block-like material (e.g. `note_block`) as the base for a non-block item, so players can't place it as a block. (Default: false)"},
  "allowed_projectiles": {"zh":"决定了什么弹药可以装在弩和弓上","en":"Determines which item can be loaded into crossbows and bows"},
  "settings.allowed_projectiles": {"zh":"决定了什么弹药可以装在弩和弓上","en":"Determines which item can be loaded into crossbows and bows"},
  "projectile": {"zh":"基于该物品创建一个自定义弹射物实体。支持 `trident`、`arrow`、`snowball` 等类型。","en":"Creates a custom projectile entity based on the item. It supports `trident`, `arrow`, `snowball` and more."},
  "settings.projectile": {"zh":"基于该物品创建一个自定义弹射物实体。支持 `trident`、`arrow`、`snowball` 等类型。","en":"Creates a custom projectile entity based on the item. It supports `trident`, `arrow`, `snowball` and more."},
  "dyeable": {"zh":"控制物品是否可以在工作台中染色。（默认值：未定义）","en":"Decides if the item can be dyed in crafting tables. (Default: undefined)"},
  "settings.dyeable": {"zh":"控制物品是否可以在工作台中染色。（默认值：未定义）","en":"Decides if the item can be dyed in crafting tables. (Default: undefined)"},
  "food": {"zh":"基于插件的 food 组件替代实现方案。","en":"Plugin-based alternative implementation for the food component."},
  "settings.food": {"zh":"基于插件的 food 组件替代实现方案。","en":"Plugin-based alternative implementation for the food component."},
  "consume_replacement": {"zh":"控制物品消耗后返回的物品。例如，玩家喝完水瓶后，会返回空瓶。（默认值：null）","en":"Set the return item after consuming the item. For example, after the player drinks the water bottle, the empty bottle will be returned. (Default: null)"},
  "settings.consume_replacement": {"zh":"控制物品消耗后返回的物品。例如，玩家喝完水瓶后，会返回空瓶。（默认值：null）","en":"Set the return item after consuming the item. For example, after the player drinks the water bottle, the empty bottle will be returned. (Default: null)"},
