  "settings.craft_remainder": {"zh":"控制在合成配方完成后，物品是否应返还其他物品，或是对参与合成的物品进行一些特殊操作。","en":"Choose whether items should return other items when the crafting recipe is finished."},
  "fuel_remainder": {"zh":"作为燃料消耗后会返还的物品，仅适用于堆叠数量为1的物品。","en":"Returned after being consumed as fuel. Only applies to items with a stack size of 1"},
  "settings.fuel_remainder": {"zh":"作为燃料消耗后会返还的物品，仅适用于堆叠数量为1的物品。","en":"Returned after being consumed as fuel. Only applies to items with a stack size of 1"},
  "enchantable": {"zh":"控制物品是否可在附魔台上被附魔。提示：将此项设置为 true 并不会神奇地让原本不可附魔的物品变得可附魔。（默认值：true）","en":"This option lets you block certain items from being used on the enchantment table. Tip: setting it to true won't magically make unenchantable items enchantable. (Default: true)"},
  "settings.enchantable": {"zh":"控制物品是否可在附魔台上被附魔。提示：将此项设置为 true 并不会神奇地让原本不可附魔的物品变得可附魔。（默认值：true）","en":"This option lets you block certain items from being used on the enchantment table. Tip: setting it to true won't magically make unenchantable items enchantable. (Default: true)"},
  "compost_probability": {"zh":"控制物品堆肥成功的几率（默认值：0.5）。","en":"This setting controls how likely it is for composting to succeed (Default: 0.5)."},
  "settings.compost_probability": {"zh":"控制物品堆肥成功的几率（默认值：0.5）。","en":"This setting controls how likely it is for composting to succeed (Default: 0.5)."},
  "respect_repairable_component": {"zh":"控制物品在铁砧界面中是否允许被 repairable 组件中指定的物品修复。（默认值：false）","en":"This controls if the items listed in repairable component can fix this item in anvil gui. (Default: false)"},
